pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    if let Some(sequence) = decode_v2_heartbeat(bytes) {
        return Ok(Msg::Heartbeat(sequence));
    }
    if let Some(value) = decode_v2_hello(bytes) {
        return Ok(Msg::Hello(value));
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!(
            r#"{{"v":2,"type":"hello","value":"{}"}}"#,
            escape_json(value)
        ),
        Msg::Heartbeat(sequence) => format!(
            r#"{{"v":2,"type":"heartbeat","seq":{}}}"#,
            sequence
        ),
    }
}

fn decode_v2_heartbeat(bytes: &str) -> Option<u32> {
    let prefix = r#"{"v":2,"type":"heartbeat","seq":"#;
    let sequence = bytes.strip_prefix(prefix)?.strip_suffix('}')?;
    sequence.parse().ok()
}

fn decode_v2_hello(bytes: &str) -> Option<String> {
    let prefix = r#"{"v":2,"type":"hello","value":""#;
    let value = bytes.strip_prefix(prefix)?.strip_suffix("\"}")?;
    unescape_json(value)
}

fn escape_json(value: &str) -> String {
    value
        .replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
        .replace('\r', "\\r")
        .replace('\t', "\\t")
}

fn unescape_json(value: &str) -> Option<String> {
    let mut result = String::with_capacity(value.len());
    let mut escaped = false;
    for character in value.chars() {
        if escaped {
            result.push(match character {
                '"' => '"',
                '\\' => '\\',
                'n' => '\n',
                'r' => '\r',
                't' => '\t',
                _ => return None,
            });
            escaped = false;
        } else if character == '\\' {
            escaped = true;
        } else if character == '"' {
            return None;
        } else {
            result.push(character);
        }
    }
    (!escaped).then_some(result)
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    #[test]
    fn heartbeat_roundtrip() {
        let message = Msg::Heartbeat(42);
        let encoded = encode(&message);

        assert!(matches!(decode(&encoded), Ok(Msg::Heartbeat(42))));
    }
}
